// Removing the constraint breaks the method body, not just its declaration
public static T Later<T>(T left, T right) /* where T : IComparable<T> removed */ =>
    left.CompareTo(right) >= 0 ? left : right;   // CS0117: 'T' does not contain a definition for 'CompareTo'

// Compiles: DateTime and int both implement IComparable<T>
GenericRules.Later(entryA.ClockIn, entryB.ClockIn);
GenericRules.Later(employeeA.EmployeeId, employeeB.EmployeeId);

